INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — IFRS revaluation model vs GAAP historical cost trade-off
(2, 'Conceptual Framework and Standards', 'Redwood International operates in both the U.S. and the U.K. and must prepare financial statements under both U.S. GAAP and IFRS. The company owns a factory purchased for $4,200,000 that has appreciated to $6,500,000 due to location demand. The CFO is evaluating whether the IFRS revaluation model under IAS 16 or the U.S. GAAP historical cost model better serves investors. Which statement best evaluates the trade-off between these approaches?', '["The revaluation model is always preferable because fair value provides superior relevance for all asset types", "Historical cost is always preferable because it eliminates subjectivity from financial reporting", "The revaluation model improves relevance for appreciated assets but introduces measurement uncertainty that reduces verifiability", "Both approaches produce equivalent investor-useful information because total lifetime expense is identical"]'::jsonb, 2, 'Under SFAC No. 8 and IAS 16, the revaluation model permits upward adjustments to fair value, increasing relevance when market values diverge from historical cost. However, fair value estimates for non-financial assets require judgment, reducing verifiability — an enhancing qualitative characteristic under the FASB framework. U.S. GAAP (ASC 360) prohibits revaluation, prioritizing verifiability and comparability. Choice A is incorrect because revaluation is not universally superior; for assets without observable market prices, reliability concerns may outweigh relevance gains.', 'hard', 4),

-- Q2: easy / L1 — Monetary unit assumption
(2, 'Conceptual Framework and Standards', 'Under the FASB Conceptual Framework, which assumption requires that financial transactions be recorded in a common denomination of currency?', '["Monetary unit assumption", "Going concern assumption", "Periodicity assumption", "Economic entity assumption"]'::jsonb, 0, 'Under SFAC No. 8, the monetary unit assumption requires that financial information be expressed in units of currency, such as the U.S. dollar. This assumption also implies that the unit of measure remains reasonably stable over time, ignoring the effects of inflation. Choice B is incorrect because the going concern assumption addresses the entity''s ability to continue operating for the foreseeable future, not the unit of measurement used in reporting.', 'easy', 1),

-- Q3: medium / L3 — Accrual vs cash basis effect on financial statements
(2, 'Conceptual Framework and Standards', 'Pinecrest Services LLC performed $85,000 of consulting work in December 2025 but did not collect payment until January 2026. Under the accrual basis of accounting, how does this transaction affect the December 2025 financial statements compared to the cash basis?', '["Accrual basis reports higher revenue and higher assets in December; cash basis reports neither", "Accrual basis reports higher liabilities in December; cash basis reports higher revenue", "Both bases report the same revenue in December because the work was completed", "Accrual basis reports lower net income in December because it must also accrue related expenses"]'::jsonb, 0, 'Under SFAC No. 5 and ASC 606, the accrual basis recognizes revenue when earned, regardless of cash receipt. Pinecrest earned the $85,000 in December 2025 when services were performed, recording revenue and an accounts receivable (asset). Under the cash basis, no entry occurs until cash is collected in January 2026. Choice D is incorrect because while the matching principle may require related expense accrual, the question asks about revenue and asset effects, which are clearly higher under the accrual basis.', 'medium', 3),

-- Q4: hard / L4 — IFRS development cost capitalization (TIPARA criteria)
(2, 'Conceptual Framework and Standards', 'Vertex Biotech Inc. has spent $3,400,000 on a drug development project that has received preliminary FDA approval. The project meets all six IAS 38 capitalization criteria — technical feasibility, intention to complete, probable future economic benefits, ability to use or sell, available resources, and ability to measure costs reliably. The controller must prepare both U.S. GAAP and IFRS financial statements. Evaluate the appropriate treatment under each framework.', '["Both frameworks require capitalization once all six criteria are met", "Both frameworks require immediate expensing of all research and development costs", "U.S. GAAP capitalizes the development costs while IFRS requires expensing", "IFRS requires capitalization of the $3,400,000 development costs, while U.S. GAAP requires expensing under ASC 730"]'::jsonb, 3, 'Under IAS 38, development costs must be capitalized when all six criteria (TIPARA) are met — capitalization is mandatory, not optional. Under U.S. GAAP (ASC 730), research and development costs are expensed as incurred, regardless of the project''s stage or likelihood of success. Choice B is incorrect because IFRS explicitly distinguishes research (always expensed) from development (capitalized when criteria are met), creating a significant divergence from U.S. GAAP''s blanket expensing requirement.', 'hard', 4),

-- Q5: hard / L4 — Neutrality vs conservatism/prudence across FASB and IASB
(2, 'Conceptual Framework and Standards', 'During a joint standard-setting discussion, a board member argues that the conceptual framework should incorporate asymmetric prudence — requiring more persuasive evidence for recognizing gains than losses — to protect users from overstated assets. Another member contends this conflicts with neutrality. The FASB''s SFAC No. 8 and the IASB''s revised Conceptual Framework take different positions on this issue. Evaluate which statement best reflects the current state of both frameworks.', '["Both frameworks include asymmetric prudence as a component of faithful representation", "The IASB framework reintroduced prudence as an aspect of neutrality, while the FASB framework excludes conservatism as inconsistent with neutrality", "Both frameworks explicitly reject any form of conservatism or prudence", "The FASB framework includes conservatism as a fundamental characteristic, while the IASB removed it"]'::jsonb, 1, 'Under SFAC No. 8, the FASB deliberately excluded conservatism from the qualitative characteristics, reasoning that asymmetric treatment conflicts with neutrality — a component of faithful representation. The IASB, in its 2018 revised Conceptual Framework, reintroduced prudence (cautious judgment under uncertainty) as supporting neutrality rather than conflicting with it. Choice C is incorrect because the IASB explicitly retained prudence, defining it as the exercise of caution in making judgments under conditions of uncertainty.', 'hard', 4),

-- Q6: medium / L2 — Periodicity assumption applied to interim reporting
(2, 'Conceptual Framework and Standards', 'Crestview Manufacturing prepares quarterly financial statements for its bank lender as required by a loan covenant. The fiscal year ends December 31. The controller argues that recognizing a $120,000 annual property tax bill entirely in Q1 — when the bill is received — is appropriate because the full amount is legally owed. Under the periodicity assumption, what is the correct treatment?', '["Recognize the full $120,000 in Q1 because the legal obligation exists at that point", "Defer recognition until Q4 when the fiscal year ends and the full picture is available", "Allocate $30,000 to each quarter because the periodicity assumption requires meaningful interim measurement", "Recognize $120,000 in Q1 and reverse $90,000 at year-end"]'::jsonb, 2, 'Under SFAC No. 8 and ASC 270, the periodicity assumption divides an entity''s economic life into discrete time periods for reporting. This requires that expenses benefiting multiple periods be allocated systematically. The $120,000 property tax benefits the entire year, so $30,000 should be allocated to each quarter. Choice A is incorrect because while the legal obligation may arise in Q1, the conceptual framework requires interim periods to reflect the economic activity of that period, not merely the timing of cash disbursements.', 'medium', 2),

-- Q7: medium / L2 — Confirmatory value component of relevance
(2, 'Conceptual Framework and Standards', 'Northridge Electronics reported estimated warranty expense of $250,000 in its 2024 financial statements. In 2025, actual warranty claims totaled $310,000. Investors use this actual outcome to assess the accuracy of Northridge''s original estimate. Under the FASB Conceptual Framework, which component of relevance does the 2025 actual warranty data provide to investors?', '["Confirmatory value, because it enables investors to validate or adjust prior expectations about warranty costs", "Predictive value, because it helps investors forecast next year''s warranty claims", "Faithful representation, because the actual amount corrects the prior estimate", "Timeliness, because the information is received within the reporting period"]'::jsonb, 0, 'Under SFAC No. 8 (QC7-QC10), relevance has two components: predictive value and confirmatory value. Information has confirmatory value when it provides feedback about prior evaluations. The actual $310,000 in warranty claims confirms or corrects investors'' prior assessment of the $250,000 estimate, serving a confirmatory role. Choice B is incorrect because while the data may also have predictive value for future periods, the question specifically asks about evaluating a prior estimate''s accuracy, which is the definition of confirmatory value.', 'medium', 2),

-- Q8: medium / L2 — Full disclosure for reasonably possible contingency
(2, 'Conceptual Framework and Standards', 'Baxter Industries has a pending lawsuit with an estimated loss of $2,000,000 that is reasonably possible but not probable. Legal counsel advises that disclosing the specific dollar amount could prejudice the litigation outcome. Under the FASB Conceptual Framework and ASC 450, what is Baxter''s disclosure obligation?', '["No disclosure is required because the loss is only reasonably possible, not probable", "Baxter must recognize a $2,000,000 liability and disclose the details in the notes", "Baxter may omit all references to the lawsuit to protect its legal position", "Baxter must disclose the nature of the contingency and may omit the estimated amount if disclosure would be prejudicial"]'::jsonb, 3, 'Under ASC 450-20-50, reasonably possible loss contingencies must be disclosed in the notes. While a liability is not recognized unless the loss is probable and estimable, disclosure is still required. ASC 450-20-50-4 permits omission of the specific loss estimate if disclosure would be prejudicial to the entity''s legal position, but the nature of the contingency must still be described. Choice A is incorrect because disclosure — not recognition — is required for reasonably possible contingencies under the full disclosure principle.', 'medium', 2),

-- Q9: medium / L2 — Liability definition applied to advance payment
(2, 'Conceptual Framework and Standards', 'On November 1, 2025, Glacier Corp. receives a $180,000 advance payment from a customer for consulting services to be delivered over the next six months. The controller debates whether this advance creates a liability. Applying the FASB Conceptual Framework''s definition of a liability, what is the correct classification?', '["Revenue, because Glacier has received the cash and controls the funds", "A liability, because Glacier has a present obligation to deliver services arising from a past transaction", "Equity, because the advance increases Glacier''s net assets", "A contingent liability, because performance depends on future events"]'::jsonb, 1, 'Under SFAC No. 8 (Chapter 4), a liability is a present obligation to transfer economic benefits arising from past transactions or events. Glacier''s receipt of the $180,000 advance creates an obligation to perform consulting services — a present duty arising from the past receipt of cash. This is recognized as unearned revenue (a liability) under ASC 606. Choice A is incorrect because revenue is recognized only when performance obligations are satisfied, not merely upon receipt of cash.', 'medium', 2),

-- Q10: medium / L3 — Timeliness vs verifiability trade-off
(2, 'Conceptual Framework and Standards', 'Summit Financial Corp. can release quarterly earnings either within 15 days using preliminary estimates with a 5% margin of error, or within 45 days using fully verified figures. Analysts prefer the faster release, while institutional investors demand precision. Under the FASB Conceptual Framework, analyze which enhancing qualitative characteristics are in tension.', '["Relevance and faithful representation are in conflict, and faithful representation always takes priority", "Comparability and consistency are in conflict, and the entity must follow industry practice", "Timeliness and verifiability are in tension, and the framework requires balancing both to maximize decision-usefulness", "Understandability and completeness are in conflict, and the entity should choose the simplest presentation"]'::jsonb, 2, 'Under SFAC No. 8 (QC19-QC34), timeliness and verifiability are both enhancing qualitative characteristics that can conflict. Timeliness means providing information early enough to influence decisions, while verifiability means independent observers can reach consensus on the measurement. The framework does not establish a fixed priority among enhancing characteristics — it requires preparers to maximize overall decision-usefulness through judgment. Choice A is incorrect because the tension here is between two enhancing characteristics, not between the fundamental characteristics.', 'medium', 3),

-- Q11: easy / L1 — Asset definition under the Conceptual Framework
(2, 'Conceptual Framework and Standards', 'Under the FASB Conceptual Framework, how is an asset defined?', '["A probable future sacrifice of economic benefits arising from past transactions", "An increase in equity resulting from peripheral transactions", "Cash or cash equivalents currently held by the entity", "A present right of an entity to an economic benefit"]'::jsonb, 3, 'Under SFAC No. 8 (Chapter 4, as amended), an asset is defined as a present right of an entity to an economic benefit. The key elements are: (1) a present right, (2) the entity controls it, and (3) it provides economic benefit. This updated definition replaced the prior SFAC No. 6 language of probable future economic benefits. Choice A is incorrect because it describes a liability — a present obligation to sacrifice economic benefits arising from past events.', 'easy', 1),

-- Q12: medium / L3 — Change in estimate vs error correction
(2, 'Conceptual Framework and Standards', 'Ironclad Manufacturing estimated a 10-year useful life for production equipment in 2020. In 2025, new information indicates only 7 total years of useful life remain. Separately, a review reveals that a $45,000 repair in 2023 was incorrectly capitalized as an asset. Under ASC 250, analyze how the treatment of these two items differs.', '["Both items require retrospective restatement of prior financial statements", "The useful life revision is a change in estimate applied prospectively, while the capitalization error requires retrospective restatement", "Both items are changes in estimates applied prospectively from 2025 forward", "The useful life revision requires retrospective restatement, while the capitalization error is applied prospectively"]'::jsonb, 1, 'Under ASC 250-10-45, changes in accounting estimates are recognized prospectively — Ironclad adjusts depreciation from 2025 forward using the revised remaining life. In contrast, ASC 250-10-45-23 requires that corrections of errors be treated retrospectively by restating prior-period financial statements. The incorrect capitalization of the $45,000 repair is an error, not an estimate change. Choice C is incorrect because error corrections fundamentally differ from estimate changes — errors reflect misapplication of GAAP, while estimates reflect updated information.', 'medium', 3),

-- Q13: easy / L1 — Understandability as enhancing qualitative characteristic
(2, 'Conceptual Framework and Standards', 'Under the FASB Conceptual Framework, which enhancing qualitative characteristic requires that financial information be presented clearly and concisely so that reasonably knowledgeable users can comprehend it?', '["Understandability", "Comparability", "Timeliness", "Verifiability"]'::jsonb, 0, 'Under SFAC No. 8 (QC30-QC32), understandability means classifying, characterizing, and presenting information clearly and concisely. Financial reports are prepared for users who have reasonable knowledge of business and economic activities. Excluding complex but relevant information to simplify reports would not improve understandability. Choice B is incorrect because comparability enables users to identify similarities and differences between entities, not to comprehend the clarity of presentation itself.', 'easy', 1),

-- Q14: hard / L4 — Evaluate restructuring liability recognition under U.S. GAAP
(2, 'Conceptual Framework and Standards', 'On December 15, 2025, Apex Technologies'' board publicly announces a plan to restructure operations, estimating $8,500,000 in severance and facility closure costs. No binding contracts have been signed and no employees have been individually notified. The CFO argues a liability should be recognized because the announcement creates a constructive obligation. Under ASC 420, evaluate whether Apex should recognize a restructuring liability at December 31, 2025.', '["Yes, because the public announcement creates a constructive obligation under U.S. GAAP", "Yes, because the board''s intent to restructure establishes a present obligation", "No, because U.S. GAAP requires a liability-incurring event such as employee notification, not merely an announcement", "No, because restructuring costs are always expensed as incurred and cannot be accrued"]'::jsonb, 2, 'Under ASC 420-10-25, a restructuring liability for one-time termination benefits is recognized when the plan is communicated to affected employees, not merely announced publicly. Unlike IFRS (IAS 37), which recognizes constructive obligations from public announcements creating valid expectations, U.S. GAAP requires specific liability-incurring events. Apex has not individually notified employees, so no liability is recognized. Choice A is incorrect because U.S. GAAP does not recognize constructive obligations from public announcements alone — this is a key GAAP/IFRS difference.', 'hard', 4),

-- Q15: hard / L4 — IFRS vs GAAP inventory write-down reversal
(2, 'Conceptual Framework and Standards', 'Global Commodities Inc. wrote down copper inventory from $1,800,000 cost to $1,200,000 net realizable value in Q3 2025 under both U.S. GAAP and IFRS. In Q4 2025, copper prices recovered and the inventory''s NRV rose to $1,650,000. The controller prepares dual financial statements. Evaluate the appropriate treatment of the recovery under each framework.', '["Under IFRS (IAS 2), reverse $450,000 of the write-down; under U.S. GAAP (ASC 330), no reversal is permitted and $1,200,000 becomes the new cost basis", "Both frameworks permit reversal of the write-down up to the original $1,800,000 cost", "Neither framework permits any reversal of inventory write-downs once recognized", "Under U.S. GAAP, reverse the write-down to $1,650,000; under IFRS, the $1,200,000 remains the permanent basis"]'::jsonb, 0, 'Under IAS 2.33, inventory write-downs are reversed when NRV recovers, but only up to the original cost — so Global reverses $450,000 ($1,650,000 minus $1,200,000). Under U.S. GAAP (ASC 330-10-35-1B), once inventory is written down to NRV, the reduced amount becomes the new cost basis and subsequent recoveries are not recognized. Choice D reverses the frameworks'' treatments — it is U.S. GAAP that prohibits reversal, not IFRS. This remains a significant inventory-related GAAP/IFRS difference.', 'hard', 4),

-- Q16: easy / L2 — Economic entity assumption
(2, 'Conceptual Framework and Standards', 'Dr. Elena Vasquez operates a pediatric dental practice as a sole proprietorship. She uses a business bank account for practice revenues but occasionally pays personal expenses from it. Her bookkeeper asks whether personal and business transactions should be combined. Under the economic entity assumption, what is the correct approach?', '["Combine all transactions because a sole proprietorship is legally inseparable from its owner", "Report only cash transactions in the business financial statements", "Separate transactions only if the practice is incorporated", "Separate the practice''s transactions from Dr. Vasquez''s personal transactions regardless of legal form"]'::jsonb, 3, 'Under SFAC No. 8, the economic entity assumption requires that the activities of an entity be kept separate from the activities of its owner and other entities. This separation applies regardless of legal structure — even sole proprietorships must distinguish business from personal transactions for meaningful financial reporting. Choice A is incorrect because while a sole proprietorship lacks legal separation, the economic entity assumption still requires accounting separation for reporting purposes.', 'easy', 2),

-- Q17: easy / L1 — Expense definition under the Conceptual Framework
(2, 'Conceptual Framework and Standards', 'Under the FASB Conceptual Framework, how are expenses defined?', '["Decreases in equity from the distribution of assets to owners", "Outflows or using up of assets from an entity''s ongoing major or central operations", "Decreases in equity from peripheral or incidental transactions", "Any reduction in the fair value of assets held by the entity"]'::jsonb, 1, 'Under SFAC No. 8 (Chapter 4), expenses are outflows or other using up of assets, or incurrences of liabilities, from delivering goods, rendering services, or carrying out other activities that constitute the entity''s ongoing major or central operations. This distinguishes expenses from losses, which arise from peripheral or incidental transactions. Choice C is incorrect because it describes losses, not expenses — the distinction depends on whether the activity is central to the entity''s operations.', 'easy', 1),

-- Q18: medium / L2 — IFRS component depreciation requirement
(2, 'Conceptual Framework and Standards', 'Hargrove Airlines purchases an aircraft for $42,000,000. The airframe has an expected useful life of 25 years, while the engines cost $12,000,000 and have a useful life of 10 years. Under IFRS, how must Hargrove depreciate this aircraft, and how does this differ from U.S. GAAP?', '["Both IFRS and U.S. GAAP require component depreciation, so the airframe and engines must be depreciated separately under both frameworks", "IFRS (IAS 16) requires component depreciation — engines and airframe depreciated separately — while U.S. GAAP permits but does not require it", "Neither framework requires component depreciation; both allow the entire aircraft to be depreciated over 25 years", "U.S. GAAP requires component depreciation while IFRS allows the entire asset to be depreciated as a single unit"]'::jsonb, 1, 'Under IAS 16.43-47, each significant component of PP&E with a different useful life must be depreciated separately. Hargrove must depreciate the $12,000,000 engines over 10 years and the $30,000,000 airframe over 25 years. Under U.S. GAAP (ASC 360), component depreciation is permitted but not required — most U.S. companies depreciate the entire asset over a single estimated life. Choice A is incorrect because the requirement is asymmetric: mandatory under IFRS, optional under U.S. GAAP.', 'medium', 2),

-- Q19: medium / L3 — Materiality is entity-specific, not a bright-line threshold
(2, 'Conceptual Framework and Standards', 'Whitaker Retail Corp. has total revenues of $800,000,000 and discovers a $2,400,000 accounting error. Sterling Boutique LLC, with total revenues of $3,200,000, discovers a $2,400,000 error of identical nature. Both controllers argue the same dollar amount should receive the same materiality treatment. Under the FASB Conceptual Framework, analyze whether this reasoning is correct.', '["The reasoning is correct because materiality depends on the absolute dollar amount of the error", "The reasoning is correct because FASB establishes a universal 5% bright-line materiality threshold", "The reasoning is incorrect because materiality is determined solely by the nature of the item, not its size", "The reasoning is incorrect because materiality is entity-specific, depending on the size and nature of the item relative to the entity''s financial statements"]'::jsonb, 3, 'Under SFAC No. 8 (QC11) and ASC 250, materiality is entity-specific and context-dependent. The $2,400,000 error is 0.3% of Whitaker''s revenue (likely immaterial) but 75% of Sterling''s revenue (clearly material). The Conceptual Framework does not establish bright-line thresholds — preparers must exercise judgment considering both quantitative magnitude and qualitative nature relative to the entity''s circumstances. Choice A is incorrect because the same dollar amount can be material for one entity and immaterial for another depending on size.', 'medium', 3),

-- Q20: easy / L1 — FASB Concepts Statements are nonauthoritative
(2, 'Conceptual Framework and Standards', 'Under ASC 105, what is the authoritative status of FASB Concepts Statements within the U.S. GAAP hierarchy?', '["They are the most authoritative source of U.S. GAAP", "They are nonauthoritative and do not establish GAAP requirements", "They are authoritative for governmental entities only", "They are authoritative when no ASC topic addresses a transaction"]'::jsonb, 1, 'Under ASC 105-10-05-3, FASB Concepts Statements (such as SFAC No. 8) are explicitly identified as nonauthoritative. They provide the conceptual foundation for developing accounting standards but do not themselves establish GAAP requirements. The sole authoritative source for nongovernmental entities is the FASB ASC. Choice D is incorrect because even when no codification topic addresses a transaction, Concepts Statements remain nonauthoritative — they may inform analogical reasoning but do not override the codification''s authority.', 'easy', 1),

-- Q21: medium / L3 — Revenue vs gains distinction
(2, 'Conceptual Framework and Standards', 'Brookfield Manufacturing sells custom machinery as its primary business, generating $15,000,000 in annual sales. The company also sold unused land adjacent to its factory for a $400,000 profit. Under the FASB Conceptual Framework, analyze how the income statement classification of these two items differs.', '["Machinery sales are revenue from central operations; the land profit is a gain from a peripheral transaction — the distinction depends on whether the activity is ongoing and central", "Both items are revenue because they both increase net assets and result from exchange transactions", "Both items are gains because they both represent increases in equity from transactions with external parties", "Machinery sales are gains and the land sale is revenue because gains must exceed $1,000,000"]'::jsonb, 0, 'Under SFAC No. 8 (Chapter 4), revenues arise from an entity''s ongoing major or central operations, while gains arise from peripheral or incidental transactions. Brookfield''s machinery sales are revenues because manufacturing is its core business. The land sale is a gain because it is incidental — Brookfield is not in the business of selling real estate. Choice B is incorrect because the framework explicitly distinguishes revenues from gains based on the nature of the activity relative to the entity''s ongoing operations.', 'medium', 3),

-- Q22: hard / L3 — IFRS vs GAAP contingent liability recognition thresholds
(2, 'Conceptual Framework and Standards', 'Cascade Pharmaceuticals faces a product liability lawsuit. Outside counsel estimates a 60% probability of adverse outcome with an expected loss of $5,200,000. Under ASC 450, "probable" generally means likelihood exceeding 75%, while under IAS 37, "probable" means more likely than not (exceeding 50%). Analyze the recognition differences between the two frameworks for this lawsuit.', '["Both frameworks require recognition because 60% exceeds the threshold under both standards", "Neither framework recognizes a liability because 60% probability is insufficient under both standards", "IFRS requires recognizing a provision because 60% exceeds the more-likely-than-not threshold, while U.S. GAAP requires only disclosure because 60% does not meet the probable threshold", "U.S. GAAP requires recognition while IFRS requires only disclosure because IFRS uses a higher probability threshold"]'::jsonb, 2, 'Under IAS 37.14, a provision is recognized when an outflow is probable, defined as more likely than not (greater than 50%). At 60% probability, Cascade recognizes a $5,200,000 provision under IFRS. Under ASC 450-20-25, probable means the event is likely to occur, interpreted in practice as exceeding approximately 75%. At 60%, the loss is reasonably possible — requiring disclosure but not recognition. Choice D reverses the frameworks'' thresholds — IFRS uses the lower threshold (greater than 50%), not the higher one.', 'hard', 3),

-- Q23: medium / L3 — Net realizable value vs fair value measurement attributes
(2, 'Conceptual Framework and Standards', 'Townsend Electronics holds obsolete tablet inventory with a cost of $320,000, a selling price of $290,000, estimated completion costs of $15,000, and estimated selling costs of $25,000. A willing buyer has offered $275,000 in an orderly transaction. Under the Conceptual Framework, analyze the difference between measuring this inventory at net realizable value versus fair value.', '["Net realizable value and fair value produce the same result of $275,000 because both reflect market conditions", "Net realizable value is $250,000 (selling price minus costs to complete and sell), while fair value is $275,000 (the orderly transaction price) — they serve different measurement objectives", "Net realizable value is $290,000 (the selling price), while fair value is $320,000 (the historical cost)", "Both measurements equal $290,000 because the selling price is the only relevant input"]'::jsonb, 1, 'Under ASC 330-10-35, net realizable value equals estimated selling price ($290,000) minus costs to complete ($15,000) and costs to sell ($25,000), totaling $250,000. Under ASC 820, fair value is the exit price in an orderly transaction between market participants — the $275,000 offer. NRV is entity-specific (includes the entity''s own costs), while fair value is market-based. Choice A is incorrect because NRV and fair value differ conceptually — NRV deducts entity-specific costs while fair value reflects the market participant perspective.', 'medium', 3),

-- Q24: easy / L1 — Present value measurement attribute
(2, 'Conceptual Framework and Standards', 'Under the FASB Conceptual Framework, which measurement attribute represents the discounted value of future cash inflows or outflows associated with an item?', '["Historical cost", "Current replacement cost", "Net realizable value", "Present value of future cash flows"]'::jsonb, 3, 'Under SFAC No. 5 and SFAC No. 8, present value of future cash flows measures an asset or liability at the discounted amount of future net cash inflows or outflows expected to arise from the item. This measurement is commonly used for long-term receivables, lease liabilities, and pension obligations. Choice A is incorrect because historical cost measures the exchange price at the date of acquisition, without considering the time value of money or future cash flow expectations.', 'easy', 1),

-- Q25: easy / L1 — Equity defined as residual interest
(2, 'Conceptual Framework and Standards', 'Under the FASB Conceptual Framework, how is equity defined for a business entity?', '["The residual interest in the assets of an entity after deducting its liabilities", "The total market value of an entity''s outstanding common stock", "The amount of cash available for distribution to shareholders", "The historical cost of all assets contributed by owners"]'::jsonb, 0, 'Under SFAC No. 8 (Chapter 4), equity is defined as the residual interest in the assets of an entity that remains after deducting its liabilities. Equity is not independently measured — it is derived from the difference between total assets and total liabilities. Choice B is incorrect because equity in the conceptual framework refers to the accounting measurement on the balance sheet (assets minus liabilities), not the market capitalization of the entity''s outstanding stock.', 'easy', 1),

-- Q26: medium / L2 — Expense recognition (matching principle) applied to prepaid insurance
(2, 'Conceptual Framework and Standards', 'On October 1, 2025, Fieldstone Insurance Co. pays $360,000 for a 12-month directors and officers liability insurance policy covering October 2025 through September 2026. Under the FASB Conceptual Framework''s expense recognition principles, what amount should Fieldstone report as insurance expense on its December 31, 2025 income statement?', '["$360,000, because the entire premium was paid in 2025", "$0, because the coverage period extends into 2026 and no claim has been made", "$90,000, because three months of the 12-month coverage period have been consumed", "$180,000, representing half of the annual premium"]'::jsonb, 2, 'Under SFAC No. 5 and the accrual basis of accounting, expenses are recognized when economic benefits are consumed, not when cash is paid. Fieldstone consumed three months of coverage (October through December 2025), so $90,000 ($360,000 times 3/12) is recognized as expense. The remaining $270,000 is a prepaid asset at year-end. Choice A is incorrect because the cash-basis approach of expensing the full $360,000 at payment ignores the systematic allocation required when benefits extend across multiple periods.', 'medium', 2),

-- Q27: medium / L2 — Completeness requirement of faithful representation
(2, 'Conceptual Framework and Standards', 'Ridgeway Corp. prepares its annual financial statements and includes all required disclosures except for information about a significant related-party transaction with its CEO''s family-owned business. The controller argues the statements still faithfully represent financial position because all dollar amounts are accurate. Under the FASB Conceptual Framework, evaluate whether this position is correct.', '["The controller is correct because faithful representation requires only that reported numbers be free from error", "The controller is incorrect because faithful representation requires completeness, including all information necessary for users to understand reported transactions", "The controller is correct because related-party disclosures are supplementary and outside faithful representation", "The controller is incorrect because the omission violates timeliness, not faithful representation"]'::jsonb, 1, 'Under SFAC No. 8 (QC12-QC16), faithful representation requires three attributes: completeness, neutrality, and freedom from error. Completeness means including all information necessary for a user to understand the phenomena depicted. Omitting the related-party disclosure under ASC 850 means the financial statements lack completeness, even if reported amounts are accurate. Choice A is incorrect because free from error is only one of three attributes — faithful representation also requires that the depiction be complete and neutral.', 'medium', 2),

-- Q28: easy / L1 — Role of Accounting Standards Updates (ASUs)
(2, 'Conceptual Framework and Standards', 'What is the purpose of an Accounting Standards Update (ASU) issued by the FASB?', '["To amend the FASB ASC by adding, modifying, or removing specific accounting guidance", "To replace the FASB ASC as the authoritative source of U.S. GAAP", "To provide nonauthoritative interpretive guidance for practitioners", "To codify SEC rules into the GAAP hierarchy for public companies"]'::jsonb, 0, 'Under ASC 105, Accounting Standards Updates are the mechanism by which the FASB amends the codification. ASUs add new guidance, modify existing requirements, or remove obsolete provisions within the ASC. The ASU itself is not authoritative — once applied, the updated content within the ASC becomes the authoritative standard. Choice B is incorrect because ASUs do not replace the ASC; they update it. The FASB ASC remains the sole authoritative source of nongovernmental U.S. GAAP.', 'easy', 1),

-- Q29: medium / L2 — IFRS impairment reversal for long-lived assets
(2, 'Conceptual Framework and Standards', 'In 2024, Kensington Properties recognized a $750,000 impairment loss on a commercial building under both U.S. GAAP and IFRS, writing the carrying amount down from $3,200,000 to $2,450,000. In 2025, market conditions improve and the building''s recoverable amount increases to $2,900,000. Under IFRS (IAS 36), how should Kensington account for the recovery?', '["Both frameworks permit reversal up to the original carrying amount of $3,200,000", "Both frameworks prohibit reversal of previously recognized impairment losses on long-lived assets", "IFRS permits reversal up to the original $3,200,000, while U.S. GAAP prohibits reversal entirely", "IFRS permits reversal up to the carrying amount that would have existed without impairment (net of depreciation), while U.S. GAAP prohibits reversal"]'::jsonb, 3, 'Under IAS 36.117, impairment losses on assets other than goodwill may be reversed when conditions improve, but the reversed carrying amount cannot exceed what it would have been (net of depreciation) had no impairment been recognized. This cap prevents overstatement. Under ASC 360-10-35-20, U.S. GAAP prohibits reversal of impairment losses on long-lived assets once recognized. Choice C is incorrect because the IFRS reversal cap is the depreciation-adjusted amount, not the full original carrying amount.', 'medium', 2),

-- Q30: medium / L3 — Conservatism excluded from SFAC No. 8
(2, 'Conceptual Framework and Standards', 'During a professional development seminar, a CPA argues that the lower of cost or net realizable value rule for inventory demonstrates that conservatism remains an explicit qualitative characteristic in SFAC No. 8. Under the current FASB Conceptual Framework, analyze whether this claim is accurate.', '["The claim is accurate — conservatism is listed as a fundamental qualitative characteristic alongside relevance and faithful representation", "The claim is accurate — conservatism is an enhancing qualitative characteristic that ranks above comparability", "The claim is inaccurate — conservatism was deliberately excluded from SFAC No. 8 because asymmetric treatment conflicts with neutrality, though specific standards may produce conservative outcomes", "The claim is inaccurate — conservatism was replaced by prudence, which is now the controlling principle under both the FASB and IASB frameworks"]'::jsonb, 2, 'Under SFAC No. 8 (BC3.27), the FASB explicitly excluded conservatism from the qualitative characteristics, reasoning that biased reporting — even downward bias — conflicts with neutrality, a component of faithful representation. While specific standards like ASC 330 (lower of cost or NRV) may produce conservative outcomes, this results from the standard''s measurement rules, not from conservatism as a framework principle. Choice D is incorrect because prudence was reintroduced only in the IASB framework — the FASB did not adopt it.', 'medium', 3)
;

COMMIT;
